// Servidor web en una subred pública de la VPC 10.0.0.0/16: ruta a internet y HTTP y HTTPS abiertos.
export const vpc = {
  cidr: "10.0.0.0/16",
  subnets: [
    {
      id: "subnet-publica",
      cidr: "10.0.1.0/24",
      routes: [
        { destination: "10.0.0.0/16", target: "local" },
        { destination: "0.0.0.0/0", target: "igw-0a1b2c3d4e5f60718" },
      ],
      nacl: [
        { direction: "inbound", number: 100, action: "allow", protocol: "-1", cidr: "0.0.0.0/0" },
        { direction: "outbound", number: 100, action: "allow", protocol: "-1", cidr: "0.0.0.0/0" },
      ],
    },
  ],
  securityGroups: [
    {
      id: "sg-web",
      rules: [
        { direction: "inbound", protocol: "tcp", fromPort: 80, toPort: 80, cidr: "0.0.0.0/0" },
        { direction: "inbound", protocol: "tcp", fromPort: 443, toPort: 443, cidr: "0.0.0.0/0" },
        { direction: "outbound", protocol: "-1", cidr: "0.0.0.0/0" },
      ],
    },
  ],
};

spec.code:
const web = { ip: "10.0.1.10", securityGroups: ["sg-web"] };
const visitante = { ip: "198.51.100.7" };
const resultado = aws.network.canConnect(vpc, { from: visitante, to: web, protocol: "tcp", port: 443 });
assert.strictEqual(resultado.allowed, true, "El HTTPS no llega: " + resultado.reason);

const web = { ip: "10.0.1.10", securityGroups: ["sg-web"] };
const visitante = { ip: "198.51.100.7" };
const resultado = aws.network.canConnect(vpc, { from: visitante, to: web, protocol: "tcp", port: 80 });
assert.strictEqual(resultado.allowed, true, "El HTTP no llega: " + resultado.reason);

const subred = vpc.subnets[0];
assert.ok(subred, "Falta la subred pública");
assert.ok(aws.cidr.contains(vpc.cidr, subred.cidr), subred.cidr + " queda fuera de la VPC " + vpc.cidr);

const web = { ip: "10.0.1.10", securityGroups: ["sg-web"] };
const visitante = { ip: "198.51.100.7" };
const resultado = aws.network.canConnect(vpc, { from: web, to: visitante, protocol: "tcp", port: 443 });
assert.strictEqual(resultado.allowed, true, "La salida a internet no funciona: " + resultado.reason);

const web = { ip: "10.0.1.10", securityGroups: ["sg-web"] };
const visitante = { ip: "198.51.100.7" };
const resultado = aws.network.canConnect(vpc, { from: visitante, to: web, protocol: "tcp", port: 22 });
assert.strictEqual(resultado.allowed, false, "El puerto 22 no debe quedar abierto a internet");

const destino = aws.network.routeFor(vpc.subnets[0].routes, "8.8.8.8");
assert.ok(destino !== null && destino.startsWith("igw-"), "El tráfico de internet debe salir por un internet gateway y sale por " + String(destino));
assert.strictEqual(aws.network.routeFor(vpc.subnets[0].routes, "10.0.1.50"), "local");

