spec.code:
const web = { ip: "10.10.1.10", securityGroups: ["sg-web"] };
const db = { ip: "10.10.2.10", securityGroups: ["sg-db"] };
const visitante = { ip: "198.51.100.7" };
const resultado = aws.network.canConnect(vpc, { from: visitante, to: web, protocol: "tcp", port: 443 });
assert.strictEqual(resultado.allowed, true, "El HTTPS no llega a la web: " + resultado.reason);

const web = { ip: "10.10.1.10", securityGroups: ["sg-web"] };
const db = { ip: "10.10.2.10", securityGroups: ["sg-db"] };
const visitante = { ip: "198.51.100.7" };
const resultado = aws.network.canConnect(vpc, { from: web, to: db, protocol: "tcp", port: 3306 });
assert.strictEqual(resultado.allowed, true, "La web no llega a la base de datos: " + resultado.reason);

const web = { ip: "10.10.1.10", securityGroups: ["sg-web"] };
const db = { ip: "10.10.2.10", securityGroups: ["sg-db"] };
const visitante = { ip: "198.51.100.7" };
const resultado = aws.network.canConnect(vpc, { from: visitante, to: db, protocol: "tcp", port: 3306 });
assert.strictEqual(resultado.allowed, false, "La base de datos no debe ser alcanzable desde internet");

const grupo = vpc.securityGroups.find((candidato: { id: string }) => candidato.id === "sg-db");
assert.ok(grupo, "Falta el security group sg-db");
const entra = (peer: string, port: number) => aws.network.securityGroupAllows(grupo.rules, { direction: "inbound", protocol: "tcp", port, peer });
assert.strictEqual(entra("10.10.1.50", 3306), true, "La subred web debe poder usar el 3306");
assert.strictEqual(entra("198.51.100.7", 3306), false, "Una dirección de internet no debe usar el 3306");
assert.strictEqual(entra("10.10.2.20", 3306), false, "Otra dirección fuera de la subred web no debe usar el 3306");
assert.strictEqual(entra("10.10.1.50", 22), false, "El 22 no debe estar abierto en la base de datos");

const web = { ip: "10.10.1.10", securityGroups: ["sg-web"] };
const db = { ip: "10.10.2.10", securityGroups: ["sg-db"] };
const visitante = { ip: "198.51.100.7" };
for (const port of [22, 80, 3306]) {
  const resultado = aws.network.canConnect(vpc, { from: visitante, to: web, protocol: "tcp", port });
  assert.strictEqual(resultado.allowed, false, "El puerto " + port + " no debe estar abierto a internet");
}

const web = { ip: "10.10.1.10", securityGroups: ["sg-web"] };
const db = { ip: "10.10.2.10", securityGroups: ["sg-db"] };
const visitante = { ip: "198.51.100.7" };
const resultado = aws.network.canConnect(vpc, { from: web, to: visitante, protocol: "tcp", port: 443 });
assert.strictEqual(resultado.allowed, true, "La web no sale a internet: " + resultado.reason);

assert.strictEqual(vpc.subnets.length, 2);
for (const subred of vpc.subnets as { id: string; cidr: string }[]) {
  const utilizables = aws.cidr.usableAddresses(subred.cidr);
  assert.ok(utilizables >= 250, subred.id + " ofrece " + utilizables + " direcciones utilizables y se piden 250");
}

