// Servicio de red que elige un asistente para cinco casos. Corrige la elección equivocada.
export const conectividad = {
  casos: [
    { necesidad: "Traducir el nombre de dominio de la tienda a la dirección de su aplicación", servicio: "route53" },
    { necesidad: "Servir imágenes y archivos JavaScript desde ubicaciones de borde cercanas a los usuarios", servicio: "cloudfront" },
    { necesidad: "Repartir las peticiones entre instancias de dos zonas de disponibilidad, solo a las que están en buen estado", servicio: "elb" },
    { necesidad: "Conectar la oficina con la VPC mediante túneles cifrados con IPsec", servicio: "vpn" },
    { necesidad: "Enlazar el centro de datos con AWS por un cable de fibra hasta una ubicación de Direct Connect", servicio: "directconnect" },
  ],
};

spec.code:
const fila = conectividad.casos.find((f) => f.necesidad.startsWith("Conectar la oficina"));
assert.ok(fila, "debe existir la fila de la oficina");
assert.strictEqual(fila.servicio, "vpn");

for (const fila of conectividad.casos) {
  assert.ok(["route53", "cloudfront", "elb", "vpn", "directconnect"].includes(fila.servicio), fila.necesidad + " tiene un servicio no válido");
}

const esperado = {
  "Traducir el nombre de dominio de la tienda a la dirección de su aplicación": "route53",
  "Servir imágenes y archivos JavaScript desde ubicaciones de borde cercanas a los usuarios": "cloudfront",
  "Repartir las peticiones entre instancias de dos zonas de disponibilidad, solo a las que están en buen estado": "elb",
  "Enlazar el centro de datos con AWS por un cable de fibra hasta una ubicación de Direct Connect": "directconnect",
};
for (const [necesidad, servicio] of Object.entries(esperado)) {
  const fila = conectividad.casos.find((f) => f.necesidad === necesidad);
  assert.ok(fila, necesidad + " debe seguir existiendo");
  assert.strictEqual(fila.servicio, servicio);
}
